"/* ============================================================
   TRADING DASHBOARD — Premium Dark Mode Stylesheet
   Bloomberg Terminal meets Modern Fintech
   ============================================================ */

/* ── Google Font ─────────────────────────────────────────────── */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');

/* ── CSS Custom Properties ───────────────────────────────────── */
:root {
  /* ▸ Backgrounds */
  --bg-base:          #0a0e17;
  --bg-surface:       #111827;
  --bg-surface-hover: #1a2235;
  --bg-card:          rgba(17, 24, 39, 0.65);
  --bg-card-border:   rgba(255, 255, 255, 0.06);
  --bg-sidebar:       #0d1220;
  --bg-input:         rgba(17, 24, 39, 0.80);
  --bg-overlay:       rgba(0, 0, 0, 0.70);

  /* ▸ Accent Palette */
  --clr-buy:          #10b981;
  --clr-buy-dim:      rgba(16, 185, 129, 0.15);
  --clr-buy-glow:     rgba(16, 185, 129, 0.40);
  --clr-sell:         #ef4444;
  --clr-sell-dim:     rgba(239, 68, 68, 0.15);
  --clr-sell-glow:    rgba(239, 68, 68, 0.40);
  --clr-hold:         #f59e0b;
  --clr-hold-dim:     rgba(245, 158, 11, 0.15);
  --clr-hold-glow:    rgba(245, 158, 11, 0.40);
  --clr-primary:      #3b82f6;
  --clr-primary-dim:  rgba(59, 130, 246, 0.15);
  --clr-primary-glow: rgba(59, 130, 246, 0.40);
  --clr-ict:          #8b5cf6;
  --clr-ict-dim:      rgba(139, 92, 246, 0.15);
  --clr-ict-glow:     rgba(139, 92, 246, 0.40);

  /* ▸ Text */
  --text-primary:     #f1f5f9;
  --text-secondary:   #94a3b8;
  --text-muted:       #475569;
  --text-inverse:     #0a0e17;

  /* ▸ Borders */
  --border-subtle:    rgba(255, 255, 255, 0.06);
  --border-light:     rgba(255, 255, 255, 0.10);
  --border-focus:     rgba(59, 130, 246, 0.50);

  /* ▸ Radii */
  --radius-sm:  6px;

